namespace Notes.Core.Sync;

/// <summary>Common sync fields shared by every synchronized entity of every module.</summary>
public abstract class SyncEntity
{
    /// <summary>UUIDv7, generated by the client that created the entity.</summary>
    public Guid Id { get; set; }

    public DateTime CreatedAt { get; set; }

    /// <summary>Time of the last change as reported by the client that made it (UTC, millisecond precision).</summary>
    public DateTime ModifiedAt { get; set; }

    /// <summary>Tombstone. Entities are never hard-deleted immediately.</summary>
    public DateTime? DeletedAt { get; set; }

    /// <summary>Server-assigned, globally monotonically increasing change number.</summary>
    public long Version { get; set; }

    /// <summary>
    /// JSON object holding fields this server version does not know (sent by newer clients).
    /// They are preserved and sent back on pull so nothing gets lost in a version mix.
    /// </summary>
    public string? ExtraJson { get; set; }

    public bool IsDeleted => DeletedAt is not null;
}

/// <summary>Base for all module entities: each belongs to exactly one context.</summary>
public abstract class ContextScopedEntity : SyncEntity
{
    public Guid ContextId { get; set; }
}

/// <summary>Declares the sync entity type name (e.g. <c>stickies.sticky</c>) of an entity class.</summary>
[AttributeUsage(AttributeTargets.Class, Inherited = false)]
public sealed class SyncEntityTypeAttribute(string name) : Attribute
{
    public string Name { get; } = name;

    public static string Of(Type type) =>
        type.GetCustomAttributes(typeof(SyncEntityTypeAttribute), false).OfType<SyncEntityTypeAttribute>().FirstOrDefault()?.Name
        ?? throw new InvalidOperationException($"{type.Name} has no [SyncEntityType].");
}
